// GENERATED by scripts/sync.js from renderer/combobox.js — edit the original, then run `npm run sync`.
// Dropdown with type-to-filter and "+ Add" for new values.
// opts.options()        -> [{ value, custom }] current list
// opts.onAdd(value)     -> Promise, persists a new value
// opts.onRemove(value)  -> Promise, removes a custom value
// opts.onChange(value)  -> called when the input value changes by selection
function createCombobox(input, opts) {
  const wrap = document.createElement('div');
  wrap.className = 'combo';
  input.parentNode.insertBefore(wrap, input);
  wrap.appendChild(input);
  input.setAttribute('autocomplete', 'off');

  const toggle = document.createElement('button');
  toggle.type = 'button';
  toggle.className = 'combo-toggle';
  toggle.tabIndex = -1;
  toggle.innerHTML = '▾';
  wrap.appendChild(toggle);

  const list = document.createElement('div');
  list.className = 'combo-list hidden';
  wrap.appendChild(list);

  let items = [];
  let active = -1;
  let showAll = false;

  const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));

  function build() {
    const typed = input.value.trim();
    const q = showAll ? '' : typed.toLowerCase();
    const all = opts.options();
    const matches = all.filter((o) => !q || o.value.toLowerCase().includes(q));
    const exact = all.some((o) => o.value.toLowerCase() === typed.toLowerCase());
    items = matches.map((o) => ({ type: 'option', ...o }));
    if (typed && !exact) items.unshift({ type: 'add', value: typed });
    active = items.findIndex((i) => i.type === 'option' && i.value === input.value);
    if (active < 0 && items.length) active = 0;
    list.innerHTML = items.length
      ? items.map((it, i) => it.type === 'add'
        ? `<div class="combo-item add ${i === active ? 'active' : ''}" data-i="${i}">+ Add “${esc(it.value)}”</div>`
        : `<div class="combo-item ${i === active ? 'active' : ''} ${it.value === input.value ? 'selected' : ''}" data-i="${i}">
             <span>${esc(it.value)}</span>${it.custom ? `<span class="combo-del" data-del="${i}" title="Remove from list">×</span>` : ''}</div>`
      ).join('')
      : '<div class="combo-empty">No options</div>';
  }

  function open(all = false) {
    showAll = all;
    build();
    list.classList.remove('hidden');
    list.querySelector('.active')?.scrollIntoView({ block: 'nearest' });
  }

  function close() {
    list.classList.add('hidden');
  }

  function setValue(v) {
    input.value = v;
    input.dispatchEvent(new Event('input', { bubbles: true }));
    opts.onChange?.(v);
  }

  async function choose(i) {
    const it = items[i];
    if (!it) return;
    if (it.type === 'add') {
      try {
        await opts.onAdd(it.value);
      } catch (err) {
        console.error(err);
      }
    }
    setValue(it.value);
    close();
  }

  input.addEventListener('focus', () => open(true));
  input.addEventListener('click', () => open(true));
  input.addEventListener('input', (e) => {
    if (e.isTrusted) open(false);
  });
  input.addEventListener('blur', () => setTimeout(close, 150));
  input.addEventListener('keydown', (e) => {
    const isOpen = !list.classList.contains('hidden');
    if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
      e.preventDefault();
      if (!isOpen) return open(true);
      if (!items.length) return;
      active = (active + (e.key === 'ArrowDown' ? 1 : -1) + items.length) % items.length;
      list.querySelectorAll('.combo-item').forEach((el, i) => el.classList.toggle('active', i === active));
      list.querySelector('.active')?.scrollIntoView({ block: 'nearest' });
    } else if (e.key === 'Enter' && isOpen && active >= 0) {
      e.preventDefault();
      choose(active);
    } else if (e.key === 'Escape') {
      close();
    }
  });

  toggle.addEventListener('mousedown', (e) => {
    e.preventDefault();
    if (list.classList.contains('hidden')) {
      input.focus();
      open(true);
    } else {
      close();
    }
  });

  list.addEventListener('mousedown', async (e) => {
    e.preventDefault(); // keep focus in the input
    const del = e.target.closest('[data-del]');
    if (del) {
      const it = items[Number(del.dataset.del)];
      await opts.onRemove(it.value);
      build();
      return;
    }
    const row = e.target.closest('[data-i]');
    if (row) choose(Number(row.dataset.i));
  });

  return { refresh: () => !list.classList.contains('hidden') && build(), open, close };
}
